function acquisitionContext(selected, rows = loadCandidatePool()) {
  const ctx = buildGroupRecommendationContext(selected, rows);
  const artists = loadLastFmArtistPool(), feedback = loadFeedback();
  ctx.retentionSnapshot = { artists, exact: new Set(loadLastFmTrackPool().map(row => trackSignatureFromParts(row.track, [row.artist]))), feedback };
  ctx.retentionFeedback = { data: feedback, artistStats: feedbackArtistStats(feedback), hardBlocked: feedbackBlockedArtistNames() };
  // Match the original first-row lookup even for duplicate legacy imports.
  ctx.acquisitionVariantArtists = new Map([...artists].reverse().map(row => [normalizeArtistName(row.artist), row]));
  return ctx;
}

functions.retainSpotifyPool:
function retainSpotifyPool(pool) {
  if (pool.length <= CANDIDATE_POOL_MAX_ITEMS) return pool.sort((a, b) => Number(b.savedAt || 0) - Number(a.savedAt || 0) || a.track.id.localeCompare(b.track.id));
  const allProfiles = retentionProfiles();
  const ctx = buildGroupRecommendationContext(allProfiles, pool);
  const feedback = loadFeedback(), artistStats = feedbackArtistStats(feedback), hardBlocked = feedbackBlockedArtistNames();
  ctx.retentionSnapshot = { artists: [...ctx.artistPool.values()], exact: new Set(loadLastFmTrackPool().map(row => trackSignatureFromParts(row.track, [row.artist]))), feedback };
  ctx.retentionFeedback = { data: feedback, artistStats, hardBlocked };
  const singleContexts = allProfiles.map(profile => ({ ...ctx, selected: [profile], staticCache: new Map() }));
  const previousClean = canonicalCleanVariantSignatures;
  try {
    rebuildCanonicalCleanVariantSignatures(pool, ctx.artistPool);
    const entries = pool.map(row => {
      const track = row.track, artistNames = (track.artists || []).map(a => normalizeArtistName(a.name));
      const hard = trackHasArtistExclusion(track) || Number(feedback[trackSignature(track)]?.value || 0) < 0 ||
        artistNames.some(name => hardBlocked.has(name)) || hasStrongNegativeArtistFeedback(track, artistStats) ||
        looksLikeUnwantedVariant(track, ctx.artistPool);
      const coverage = new Set();
      if (!hard) {
        for (const single of singleContexts) {
          const profile = single.selected[0];
          if (profile.blockedArtists.some(name => artistNames.includes(normalizeArtistName(name)))) continue;
          const info = groupCandidateStatic(track, single);
          const strongDiscovery = Number(discoveryLevel.value || 0) > 0 && info.maxScore >= 72 && (info.likedByAny || info.seedByAny);
          if (!recognizabilityPass(track, ctx.retentionSnapshot) && !strongDiscovery) continue;
          if (info.maxScore < 45) continue;
          if (info.groupBase >= GROUP_HARD_MIN_BASE_SCORE ||
              (info.groupBase >= GROUP_FALLBACK_MIN_BASE_SCORE && info.minScore >= GROUP_FALLBACK_MIN_USER_SCORE && info.features.feedback > GROUP_FALLBACK_MIN_FEEDBACK)) {
            coverage.add(`profile:${profile.id}`);
            for (const aspect of info.features.aspects) coverage.add(`genre:${aspect}`);
          }
        }
      }
      const primary = track.artists?.[0];
      return { row, key: track.id, artist: primary?.id ? `id:${primary.id}` : `name:${normalizeArtistName(primary?.name || "") || track.id}`,
        savedAt: row.savedAt, protected: coverage.size > 0, coverage: [...coverage] };
    });
    return OfficePoolRetention.retain(entries, CANDIDATE_POOL_MAX_ITEMS);
  } finally { canonicalCleanVariantSignatures = previousClean; }
}

functions.generateOfficePlaylist:
async function generateOfficePlaylist() {
  if (generationInFlight) return;
  generationInFlight = true;
  const total = Number(playlistLength.value);
  const progress = OmmGenerationProgress.create(progressBox, total);
  activeGenerationProgress = progress;
  const originals = new Map();
  for (const [name, metric] of [["loadCandidatePool", "localPool"], ["readSearchCache", "searchCache"], ["acquisitionCoverage", "coverage"], ["eligibleGroupCandidates", "qualification"]]) {
    const original = window[name]; originals.set(name, original);
    window[name] = function (...args) { return progress.measure(metric, () => { const value = original.apply(this, args); if (name === "loadCandidatePool") progress.update({ pool: value.length });
      if (name === "readSearchCache") progress.count(value === null ? "cacheReadMisses" : "cacheReadHits"); return value; }); };
  }
  let createdPlaylist = null, finalLength = 0;
  try {
    generateButton.disabled = true;
    newSearchesThisGeneration = 0;
    queriesAttemptedThisGeneration = new Set();
    playlistBox.style.display = "none";
    playlistResult.textContent = "";
    maxNewSearchesThisGeneration = searchBudgetForTarget(total);
    progress.update({ budget: maxNewSearchesThisGeneration });
    generationStage(0);

    const token = await getValidAccessToken();
    if (!token) throw new Error("Brak aktywnej sesji Spotify.");


    generationStage(1);
    const playlistCleanupResult = await cleanupOldOfficePlaylists(token);

    const selected = selectedProfiles();
    const bartek = selected.find(profile => profile.id === "bartek");
    if (!bartek) {
      throw new Error("Profil Bartka musi być aktywny. Jest głównym profilem tej aplikacji.");
    }
    if (!hasMusicProfile(bartek)) {
      throw new Error("Profil Bartka nie ma danych muzycznych. Wypełnij ankietę gustu lub dodaj gatunki/artystów wzorcowych.");
    }

    const mixProfiles = selected.filter(hasMusicProfile);
    const ignoredProfiles = selected.filter(profile => !hasMusicProfile(profile));

    generationStage(2);
    await refreshLastFmBeforeGeneration(mixProfiles, total);

    generationStage(3);
    await syncSpotifyRecentHistory(token);
    generationStage(4);
    if (!document.hidden && globalThis.scheduler?.yield) await scheduler.yield();
    const acquisitionBlocklists = generationBlocklists(selected);
    const acquisition = createCandidateAcquisition(mixProfiles, acquisitionBlocklists);
    acquisition.blockProfiles = selected;

    await primeManualSeedArtists(token, mixProfiles, 3, acquisition);

    const genrePrimeBudget = genrePrimeBudgetForTarget(total);
    generationStage(5);
    await primeProfileGenres(token, mixProfiles, genrePrimeBudget, acquisition);

    const remainingSearchBudget = Math.max(0, maxNewSearchesThisGeneration - newSearchesThisGeneration);
    generationStage(6);
    await primeCommonGroupQueries(token, mixProfiles, Math.min(3, remainingSearchBudget), acquisition);

    generationStage(7);
    if (!document.hidden && globalThis.scheduler?.yield) await scheduler.yield();
    const blocklists = generationBlocklists(selected);
    const ctx = buildGroupRecommendationContext(mixProfiles, loadCandidatePool(), createLastFmEvidenceSnapshot());
    const { eligible, stats } = eligibleGroupCandidates(mixProfiles, blocklists, ctx);

    if (!eligible.length) {
      throw new Error("Po filtrach nie został żaden kandydat. Diagnostyka będzie wymagała poluzowania źródeł lub filtrów.");
    }

    const groupResult = selectGroupPlaylist(eligible, total, ctx, stats);
    groupResult.acquisition = { before: acquisition.before, after: getAcquisitionCoverage(acquisition).artists, cachedPages: acquisition.cachedPages, newSearches: newSearchesThisGeneration };
    const finalTracks = sequencePlaylistForListening(groupResult.tracks, 5);
    groupResult.tracks = finalTracks;

    if (!finalTracks.length) {
      throw new Error("Algorytm grupowy nie wybrał żadnego utworu.");
    }

    generationStage(8);

    const playlist = await createPlaylist(token, selected, finalTracks.length);
    createdPlaylist = playlist; progress.created();
    await addItemsToPlaylist(
      token,
      playlist.id,
      finalTracks.map(track => track.uri)
    );

    finalLength = finalTracks.length;
    generationStage(9);
    recordSeedArtistSelections(finalTracks, selected);
    // Both Spotify writes have completed. Read fresh evidence again so feedback
    // or history changed while awaiting the API is reflected in diagnostics.
    const diagnosticEvidence = createLastFmEvidenceSnapshot();
    const diagnostics = buildPlaylistDiagnostics(finalTracks, selected, groupResult, diagnosticEvidence);
    saveRecentPlaylistSnapshot(playlist, finalTracks, selected, total, groupResult, diagnosticEvidence, diagnostics);
    renderPlaylistResult(
      playlist,
      finalTracks,
      selected,
      ignoredProfiles,
      total,
      playlistCleanupResult,
      groupResult,
      diagnosticEvidence,
      diagnostics
    );

    // Pula Spotify jest kosztowna do odbudowy, więc po udanym generowaniu zapisujemy
    // jej skompaktowaną wersję do D1 razem z trwałymi preferencjami. Błąd chmury
    // nie może unieważnić poprawnie utworzonej playlisty.
    generationStage(10);
    try {
      await uploadCloudStateIfChanged(token, { status: true });
    } catch (cloudErr) {
      console.error("Cloud sync after generation:", cloudErr);
      setCloudStatus(`po generowaniu: ${cloudErr.message}`, "error");
      progress.warn("Playlista gotowa; synchronizacja chmury nie powiodła się. Lokalny wynik został zachowany.");
    }
    progress.finish(null, finalLength);

  } catch (err) {
    console.error(err);
    progress.finish(err, finalLength);
    if (!finalLength) {
      const previous = loadRecentPlaylists()[0];
      if (previous) renderStoredPlaylistSnapshot(previous);
      else playlistResult.textContent = "";
    }
    const errorMessage = document.createElement("p"); errorMessage.className = "error"; errorMessage.textContent = err.message; playlistResult.prepend(errorMessage);
    if (createdPlaylist && !finalLength) appendSpotifyPlaylistLinks(playlistResult, createdPlaylist);
    playlistBox.style.display = "block";
  } finally {
    lastGenerationReport = progress.report();
    for (const [name, original] of originals) window[name] = original;
    activeGenerationProgress = null; generationInFlight = false;
    generateButton.disabled = false;
  }
}

functions.retentionCoverage:
function retentionCoverage(tags, allProfiles) {
  const coverage = new Set((tags || []).map(normalizeGenreName).filter(Boolean).map(tag => `tag:${tag}`));
  for (const profile of allProfiles) {
    const wanted = new Set([...(profile.taste.likedGenres || []), ...(profile.taste.okGenres || []), ...profile.manualGenres].map(normalizeGenreName));
    if ((tags || []).some(tag => lastFmTagMatchesWanted(tag, wanted))) coverage.add(`profile:${profile.id}`);
  }
  return [...coverage];
}

functions.retainLastFmPool:
function retainLastFmPool(pool, limit, tracks) {
  const allProfiles = retentionProfiles();
  const seeds = new Set(allProfiles.flatMap(p => p.artists).map(normalizeArtistName));
  return OfficePoolRetention.retain(pool.map(row => {
    const artist = normalizeArtistName(row.artist), coverage = retentionCoverage(row.tags, allProfiles);
    for (const profile of allProfiles) if (profile.artists.some(name => normalizeArtistName(name) === artist)) coverage.push(`profile:${profile.id}`);
    const recent = lastFmRecentEvidenceCount(row) > 0;
    return { row, key: tracks ? `${artist}|${normalizeForSignature(row.track)}` : artist, artist,
      savedAt: row.savedAt, protected: recent || seeds.has(artist) || coverage.some(k => k.startsWith("profile:")), coverage };
  }), limit);
}

